export const $=(s,root=document)=>root.querySelector(s);
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const date=s=>s?new Date(s).toLocaleString('zh-CN',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'—';
export function parseResponse(raw,status){let body;try{body=JSON.parse(raw);}catch{throw Error(status>=500?'服务连接暂时中断，请稍后重试。':'服务返回内容异常，请刷新页面后重试。');}if(status<200||status>=300){const e=new Error(body?.error||'请求失败，请重试');e.status=status;throw e;}return body;}
export async function api(url,method='GET',data){let res;try{res=await fetch(url,{method,credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});}catch{throw Error('网络连接中断，请检查网络后重试。');}let raw;try{raw=await res.text();}catch{throw Error('网络连接中断，请检查网络后重试。');}return parseResponse(raw,res.status);}
export const icons={discover:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5z"/>',map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3zM9 3v15M15 6v15"/>',walk:'<circle cx="14" cy="4" r="2"/><path d="m7 12 3-4 4 1 3 4h3M12 10l-2 6-4 4M11 15l5 5"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0l-1 1-1-1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',camera:'<path d="M3 7h4l2-3h6l2 3h4v14H3z"/><circle cx="12" cy="13" r="4"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="3"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',check:'<path d="m5 12 4 4 10-10"/>',book:'<path d="M4 3h14l2 3v15H4zM8 7h8M8 11h8M8 15h5"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v2M12 21v2M1 12h2M21 12h2M4 4l2 2M18 18l2 2M4 20l2-2M18 6l2-2"/>',copy:'<path d="M8 8h13v13H8zM3 16V3h13"/>',logout:'<path d="M10 3H3v18h7M8 12h13m-4-4 4 4-4 4"/>',shield:'<path d="m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6z"/><path d="m8 12 3 3 5-6"/>',settings:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M2 21v-2a7 7 0 0 1 14 0v2M17 4a3 3 0 0 1 0 6M18 14a5 5 0 0 1 4 5v2"/>',ticket:'<path d="M3 5h18v5a2 2 0 0 0 0 4v5H3v-5a2 2 0 0 0 0-4zM15 5v3m0 3v2m0 3v3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h1M3 12h1M3 18h1"/>'};
export const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.discover}</svg>`;
let toastTimer;
export function toast(message){let t=$('#toast');if(!t){t=document.createElement('div');t.id='toast';t.setAttribute('role','status');document.body.append(t);}t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3500);}
let cleanupModal=null,previousFocus;
export function closeModal(){if(cleanupModal)cleanupModal();cleanupModal=null;const d=$('#dialog');if(d){d.close();d.remove();}previousFocus?.focus?.();}
export function modal(title,html,setup){closeModal();previousFocus=document.activeElement;const d=document.createElement('dialog');d.id='dialog';d.innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button class="icon-btn" aria-label="关闭">${icon('close')}</button></div><div class="dialog-body">${html}</div>`;document.body.append(d);d.querySelector('.dialog-head button').onclick=closeModal;d.addEventListener('cancel',e=>{e.preventDefault();closeModal();});d.addEventListener('click',e=>{if(e.target===d){const b=d.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)closeModal();}});d.showModal();cleanupModal=setup?.(d)||null;return d;}
export async function formSubmit(e,work){e.preventDefault();const btn=e.target.querySelector('[type=submit]');btn.disabled=true;const err=e.target.querySelector('.form-error');if(err)err.textContent='';try{await work(Object.fromEntries(new FormData(e.target)),e.target);}catch(x){if(err)err.textContent=x.message;else toast(x.message);}finally{btn.disabled=false;}}
export function field(label,name,type='text',value='',extra=''){return `<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
export const errorHTML='<p class="form-error" role="alert"></p>';
function jpegCanvas(source,width,height){if(!width||!height)throw Error('照片还没有准备好，请稍后再试。');const scale=Math.min(1,1800/Math.max(width,height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(width*scale));c.height=Math.max(1,Math.round(height*scale));const ctx=c.getContext('2d');if(!ctx)throw Error('当前浏览器无法处理照片，请换一个浏览器重试。');ctx.drawImage(source,0,0,c.width,c.height);const data=c.toDataURL('image/jpeg',.86);if(!data.startsWith('data:image/jpeg;base64,'))throw Error('照片处理失败，请选择较小的 JPEG 或 PNG 照片。');return data;}
export async function readPhoto(file){if(!file||file.size>20*1024*1024)throw Error('请选择 20MB 以内的照片');let bitmap;try{if(typeof createImageBitmap==='function'){try{bitmap=await createImageBitmap(file);return jpegCanvas(bitmap,bitmap.width,bitmap.height);}catch{}}const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('照片读取失败，请重新选择照片。'));reader.readAsDataURL(file);});const img=await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(Error('这张照片的格式无法读取。请转换为 JPEG / PNG，或用内建摄像头拍摄。'));image.src=data;});return jpegCanvas(img,img.naturalWidth,img.naturalHeight);}finally{bitmap?.close();}}
export function uploadPhoto(photo,{onProgress=()=>{},signal}={}){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();let finished=false;const abort=()=>xhr.abort();const settle=(fn,value)=>{if(finished)return;finished=true;signal?.removeEventListener('abort',abort);fn(value);};xhr.upload.onprogress=e=>onProgress({phase:'upload',loaded:e.loaded,total:e.lengthComputable?e.total:null});xhr.upload.onload=()=>onProgress({phase:'save'});xhr.onload=()=>{try{const result=parseResponse(xhr.responseText,xhr.status);if(typeof result?.id!=='string')throw Error('服务器未确认照片保存，请点击重试。');settle(resolve,result);}catch(e){settle(reject,e);}};xhr.onerror=()=>settle(reject,Error('照片上传中断，请检查网络后点击重试。'));xhr.ontimeout=()=>settle(reject,Error('照片上传超时，照片已保留，请点击重试。'));xhr.onabort=()=>{const e=Error('上传已取消');e.name='AbortError';settle(reject,e);};try{xhr.open('POST',new URL('/api/media',location.href).href,true);xhr.timeout=90000;xhr.setRequestHeader('Content-Type','application/json');signal?.addEventListener('abort',abort,{once:true});if(signal?.aborted){const e=Error('上传已取消');e.name='AbortError';settle(reject,e);return;}onProgress({phase:'upload',loaded:0,total:null});xhr.send(JSON.stringify({photo}));}catch{settle(reject,Error('无法开始上传，请刷新页面后重试。'));}});}
const photoError=e=>/expected pattern/i.test(e?.message||'')?'浏览器未能处理这张照片，请重试或选择 JPEG / PNG 照片。':e?.message||'照片处理失败，请重新选择。';
export function photoPicker(onSaved){return modal('留住这一刻',`<p class="muted">打开摄像头拍摄，或从相册选择已有照片。</p><video id="camera-view" autoplay playsinline muted hidden></video><img id="photo-preview" class="photo-preview" alt="待上传照片" hidden><div class="button-row"><button id="open-camera" class="button">${icon('camera')} 打开摄像头</button><label class="button secondary file-button">选择照片<input type="file" id="photo-file" accept="image/*" aria-label="从相册选择照片"></label><button id="capture" class="button" hidden>拍一张</button></div><section id="photo-progress" class="photo-progress" hidden><div class="upload-caption"><span id="upload-stage" role="status">准备照片</span><b id="upload-percent"></b></div><div id="upload-meter" class="upload-meter indeterminate" role="progressbar" aria-label="照片上传进度" aria-valuemin="0" aria-valuemax="100"><span></span></div><small id="upload-hint">请保持页面打开</small></section><p class="form-error" id="camera-error" role="alert"></p><button id="retry-photo" class="button secondary wide" hidden>重试保存这张照片</button>`,d=>{
 let stream,pendingPhoto,uploaded,busy=false,controller;const video=$('#camera-view',d),preview=$('#photo-preview',d),open=$('#open-camera',d),file=$('#photo-file',d),capture=$('#capture',d),retry=$('#retry-photo',d);
 const stop=()=>{stream?.getTracks().forEach(t=>t.stop());stream=null;video.srcObject=null;video.hidden=true;capture.hidden=true;};
 const lock=value=>{busy=value;open.disabled=value;file.disabled=value;file.closest('label').classList.toggle('disabled',value);capture.disabled=value;retry.disabled=value;};
 const progress=p=>{if(!d.isConnected)return;$('#photo-progress',d).hidden=false;const meter=$('#upload-meter',d);const determinate=p.phase==='upload'&&p.total;meter.classList.toggle('indeterminate',!determinate);if(determinate){const percent=Math.min(100,Math.round(p.loaded/p.total*100));meter.setAttribute('aria-valuenow',percent);meter.firstElementChild.style.width=percent+'%';$('#upload-percent',d).textContent=percent+'%';}else{meter.removeAttribute('aria-valuenow');meter.firstElementChild.style.width='';$('#upload-percent',d).textContent='';}$('#upload-stage',d).textContent=p.phase==='prepare'?'正在读取、压缩照片':p.phase==='upload'?'正在上传照片':'照片已发送，正在保存';$('#upload-hint',d).textContent=p.phase==='upload'&&p.total?`${(p.loaded/1024).toFixed(0)} / ${(p.total/1024).toFixed(0)} KB · 关闭弹窗会取消上传`:'请保持页面打开，完成后会自动提示';};
 const finish=async()=>{if(busy||!pendingPhoto||!d.isConnected)return;lock(true);retry.hidden=true;$('#camera-error',d).textContent='';controller=new AbortController();try{if(!uploaded)uploaded=await uploadPhoto(pendingPhoto,{signal:controller.signal,onProgress:progress});if(!d.isConnected)return;progress({phase:'save'});await onSaved(uploaded);if(d.isConnected){closeModal();toast('照片已保存');}}catch(e){if(d.isConnected&&e.name!=='AbortError'){const msg=e.message||'照片保存失败，请重试。';$('#camera-error',d).textContent=/expected pattern/i.test(msg)?'照片处理或服务连接异常。请重试；仍失败时选择 JPEG / PNG 照片。':msg;retry.hidden=false;$('#upload-stage',d).textContent='这次未能保存，照片已保留';$('#upload-hint',d).textContent='无需重新选图，点击下方重试；也可以重新选择照片。';$('#upload-meter',d).classList.remove('indeterminate');}}finally{if(d.isConnected)lock(false);}};
 const selected=async photo=>{pendingPhoto=photo;uploaded=null;stop();preview.src=photo;preview.hidden=false;lock(false);await finish();};
 file.onchange=async e=>{const chosen=e.target.files?.[0];if(!chosen||busy)return;lock(true);pendingPhoto=null;uploaded=null;retry.hidden=true;$('#camera-error',d).textContent='';progress({phase:'prepare'});try{const data=await readPhoto(chosen);if(d.isConnected)await selected(data);}catch(e){if(d.isConnected){$('#camera-error',d).textContent=photoError(e);$('#photo-progress',d).hidden=true;}}finally{file.value='';if(d.isConnected)lock(false);}};
 open.onclick=async()=>{if(busy)return;lock(true);try{if(!navigator.mediaDevices?.getUserMedia)throw Error('当前访问方式不支持摄像头，请通过 HTTPS 打开，也可以从相册选择照片。');stop();preview.hidden=true;stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});if(!d.isConnected){stop();return;}video.srcObject=stream;video.hidden=false;capture.hidden=false;$('#camera-error',d).textContent='';}catch(e){if(d.isConnected)$('#camera-error',d).textContent=e.name==='NotAllowedError'?'摄像头权限未开启。可在浏览器设置中允许，或选择已有照片。':e.name==='NotFoundError'?'没有找到可用摄像头，可以选择已有照片。':e.name==='NotReadableError'?'摄像头被其他程序占用，请稍后再试。':e.message;}finally{if(d.isConnected)lock(false);}};
 capture.onclick=async()=>{if(busy)return;try{if(!video.videoWidth){toast('摄像头画面还在准备，请稍后拍摄');return;}await selected(jpegCanvas(video,video.videoWidth,video.videoHeight));}catch(e){$('#camera-error',d).textContent=photoError(e);}};retry.onclick=finish;return()=>{controller?.abort();stop();};
 });}
export function passwordDialog(){modal('修改密码',`<form id="pw-form">${field('当前密码','currentPassword','password','','required autocomplete="current-password"')}${field('新密码（至少 8 位）','newPassword','password','','required minlength="8" maxlength="128" autocomplete="new-password"')}${field('再次输入新密码','confirm','password','','required autocomplete="new-password"')}${errorHTML}<button type="submit" class="button wide">保存新密码</button></form>`,d=>{$('#pw-form',d).onsubmit=e=>formSubmit(e,async f=>{if(f.newPassword!==f.confirm)throw Error('两次新密码不一致');await api('/api/auth/password','PATCH',f);closeModal();toast('密码已修改，其他登录已失效');});});}
